-- The statement each measurement type compiles to, from
-- standards/measurement-types.yaml + measurement_shapes.go. GENERATED by
-- TestMeasurementSQLGolden; regenerate with -update-measurement-golden.
-- $1 is the tenant, $2 the optional single-subject filter; a shape's own
-- parameter (fact key, producer) is $3 and the compiled predicates follow.

-- ============================================================
-- asset_class  [shape: asset, subject: asset]
-- predicate args: [monitoring]
SELECT
			a.id AS subject_id,
			a.tenant_id AS tenant_id,
			a.updated_at AS measured_at,
			a.class_key AS col_0,
			a.hostname AS col_1,
			host(a.primary_address) AS col_2,
			a.display_name AS col_3
		FROM assets a
		WHERE a.tenant_id = $1
			AND a.deleted_at IS NULL
			AND ($2::uuid IS NULL OR a.id = $2)
			AND ((lower((a.asset_status)::text) = $3))
			AND (TRUE)
		ORDER BY a.updated_at DESC

-- ============================================================
-- asset_has_location  [shape: asset, subject: asset]
-- predicate args: [monitoring]
SELECT
			a.id AS subject_id,
			a.tenant_id AS tenant_id,
			a.updated_at AS measured_at,
			(COALESCE(NULLIF(btrim(a.site), ''), NULLIF(btrim(a.region), ''), NULLIF(btrim(a.zone), ''), a.location_id::text) IS NOT NULL) AS col_0,
			a.hostname AS col_1,
			host(a.primary_address) AS col_2,
			a.display_name AS col_3,
			a.class_key AS col_4,
			a.site AS col_5,
			a.region AS col_6
		FROM assets a
		WHERE a.tenant_id = $1
			AND a.deleted_at IS NULL
			AND ($2::uuid IS NULL OR a.id = $2)
			AND ((lower((a.asset_status)::text) = $3))
			AND (TRUE)
		ORDER BY a.updated_at DESC

