-- cert_algorithm  [shape: certificate, subject: certificate]
SELECT
			c.id AS subject_id,
			c.tenant_id AS tenant_id,
			c.updated_at AS measured_at,
			c.public_key_algorithm AS col_0,
			c.common_name AS col_1,
			c.public_key_size AS col_2
		FROM certificates c
		WHERE c.tenant_id = $1
			AND ($2::uuid IS NULL OR c.id = $2)
			AND c.is_ca_certificate = false
			AND ((c.public_key_algorithm IS NOT NULL))
			AND (TRUE)
		ORDER BY c.updated_at DESC

-- ============================================================
-- cert_expiration_days  [shape: certificate, subject: certificate]
SELECT
			c.id AS subject_id,
			c.tenant_id AS tenant_id,
			now() AS measured_at,
			EXTRACT(EPOCH FROM (c.not_after - NOW())) / 86400.0 AS col_0,
			c.common_name AS col_1,
			c.public_key_algorithm AS col_2,
			c.public_key_size AS col_3,
			c.not_after AS col_4
		FROM certificates c
		WHERE c.tenant_id = $1
			AND ($2::uuid IS NULL OR c.id = $2)
			AND c.is_ca_certificate = false
			AND ((c.not_after IS NOT NULL))
			AND (TRUE)
		ORDER BY c.not_after ASC

