SELECT
			c.id AS subject_id,
			c.tenant_id AS tenant_id,
			c.updated_at AS measured_at,
			EXTRACT(EPOCH FROM (c.not_after - c.not_before)) / 86400.0 AS col_0,
			c.common_name AS col_1
		FROM certificates c
		WHERE c.tenant_id = $1
			AND ($2::uuid IS NULL OR c.id = $2)
			AND c.is_ca_certificate = false
			AND (((c.not_after IS NOT NULL) AND (c.not_before IS NOT NULL)))
			AND (TRUE)
