-- cipher_suite_name  [shape: crypto_configuration, subject: asset]
SELECT
			na.id AS subject_id,
			ci.tenant_id AS tenant_id,
			ci.last_verified_at AS measured_at,
			ci.cipher_suite AS col_0,
			na.hostname AS col_1,
			host(CASE WHEN ci.endpoint_id IS NULL THEN na.primary_address ELSE e.address END) AS col_2,
			e.fqdn AS col_3,
			e.port AS col_4,
			ci.id AS col_5
		FROM crypto_implementations ci
			JOIN assets na ON na.tenant_id = ci.tenant_id AND na.id = ci.asset_id
			LEFT JOIN asset_endpoints e ON e.tenant_id = ci.tenant_id AND e.id = ci.endpoint_id
		WHERE ci.tenant_id = $1
			AND na.deleted_at IS NULL
			AND ci.deleted_at IS NULL
			AND ($2::uuid IS NULL OR na.id = $2)
			AND ((ci.cipher_suite IS NOT NULL))
			AND (TRUE)
		ORDER BY ci.last_verified_at DESC

