-- duplicate_suspected_count  [shape: finding, subject: asset]
-- $3 = [hygiene]
-- predicate args: [hygiene duplicate_suspected monitoring]
SELECT
			a.id AS subject_id,
			a.tenant_id AS tenant_id,
			now() AS measured_at,
			(SELECT count(*) FROM findings f WHERE f.tenant_id = a.tenant_id AND f.subject_type = 'asset' AND f.subject_id = a.id AND f.detection_state = 'ACTIVE' AND (f.workflow_status <> 'SUPPRESSED' OR f.workflow_status IS NULL) AND (((lower((f.producer)::text) = $4) AND (lower((f.kind)::text) = $5)))) AS col_0,
			a.hostname AS col_1,
			host(a.primary_address) AS col_2,
			a.display_name AS col_3,
			a.class_key AS col_4
		FROM assets a
		WHERE a.tenant_id = $1
			AND a.deleted_at IS NULL
			AND ($2::uuid IS NULL OR a.id = $2)
			AND EXISTS (SELECT 1 FROM producer_assessments pa WHERE pa.tenant_id = a.tenant_id AND pa.asset_id = a.id AND pa.producer = $3)
			AND ((lower((a.asset_status)::text) = $6))
		ORDER BY a.updated_at DESC

