-- ============================================================
-- ot_protocol_encryption  [shape: crypto_configuration, subject: asset]
-- predicate args: [modbus dnp3 mms iccp bacnet bacnet_sc ethernet_ip opc_ua hart_ip s7]
SELECT
			na.id AS subject_id,
			ci.tenant_id AS tenant_id,
			ci.last_verified_at AS measured_at,
			CASE WHEN COALESCE(NULLIF(ci.cipher_suite, ''), '') <> '' OR COALESCE(NULLIF(ci.symmetric_encryption, ''), '') <> '' THEN 'present' ELSE 'absent' END AS col_0,
			ci.protocol::text AS col_1,
			na.hostname AS col_2,
			host(CASE WHEN ci.endpoint_id IS NULL THEN na.primary_address ELSE e.address END) AS col_3,
			e.fqdn AS col_4,
			e.port AS col_5,
			ci.id AS col_6,
			COALESCE(NULLIF(ci.cipher_suite, ''), '') AS col_7
		FROM crypto_implementations ci
			JOIN assets na ON na.tenant_id = ci.tenant_id AND na.id = ci.asset_id
			LEFT JOIN asset_endpoints e ON e.tenant_id = ci.tenant_id AND e.id = ci.endpoint_id
		WHERE ci.tenant_id = $1
			AND na.deleted_at IS NULL
			AND ci.deleted_at IS NULL
			AND ($2::uuid IS NULL OR na.id = $2)
			AND (((lower((ci.protocol)::text) = $3) OR (lower((ci.protocol)::text) = $4) OR (lower((ci.protocol)::text) = $5) OR (lower((ci.protocol)::text) = $6) OR (lower((ci.protocol)::text) = $7) OR (lower((ci.protocol)::text) = $8) OR (lower((ci.protocol)::text) = $9) OR (lower((ci.protocol)::text) = $10) OR (lower((ci.protocol)::text) = $11) OR (lower((ci.protocol)::text) = $12)))
			AND (TRUE)
		ORDER BY ci.last_verified_at DESC

