			NULLIF(af.source_ref, '') AS col_5
		FROM asset_facts af
			JOIN assets a ON a.tenant_id = af.tenant_id AND a.id = af.asset_id
		WHERE af.tenant_id = $1
			AND a.deleted_at IS NULL
			AND ($2::uuid IS NULL OR a.id = $2)
			AND af.key = $3
			AND (af.expires_at IS NULL OR af.expires_at > now())
			AND ((lower((a.asset_status)::text) = $4))
			AND (TRUE)
		ORDER BY af.observed_at DESC

-- ============================================================
-- symmetric_encryption  [shape: crypto_configuration, subject: asset]
SELECT
			na.id AS subject_id,
			ci.tenant_id AS tenant_id,
			ci.last_verified_at AS measured_at,
			ci.symmetric_encryption AS col_0,
			na.hostname AS col_1,
			host(CASE WHEN ci.endpoint_id IS NULL THEN na.primary_address ELSE e.address END) AS col_2,
			e.fqdn AS col_3,
			e.port AS col_4,
			ci.id AS col_5,
			ci.cipher_suite AS col_6
		FROM crypto_implementations ci
			JOIN assets na ON na.tenant_id = ci.tenant_id AND na.id = ci.asset_id
			LEFT JOIN asset_endpoints e ON e.tenant_id = ci.tenant_id AND e.id = ci.endpoint_id
		WHERE ci.tenant_id = $1
			AND na.deleted_at IS NULL
			AND ci.deleted_at IS NULL
			AND ($2::uuid IS NULL OR na.id = $2)
			AND ((ci.symmetric_encryption IS NOT NULL))
			AND (TRUE)
		ORDER BY ci.last_verified_at DESC

-- ============================================================
-- tls_compression_enabled  [shape: crypto_configuration, subject: asset]
-- predicate args: [tls]
SELECT
			na.id AS subject_id,
			ci.tenant_id AS tenant_id,
			ci.last_verified_at AS measured_at,
			CASE WHEN jsonb_typeof(ci.raw_data -> 'compression') = 'boolean' THEN (ci.raw_data ->> 'compression')::boolean ELSE NULL END AS col_0,
			na.hostname AS col_1,
			host(CASE WHEN ci.endpoint_id IS NULL THEN na.primary_address ELSE e.address END) AS col_2,
			e.fqdn AS col_3,
			e.port AS col_4,
			ci.id AS col_5
		FROM crypto_implementations ci
			JOIN assets na ON na.tenant_id = ci.tenant_id AND na.id = ci.asset_id
			LEFT JOIN asset_endpoints e ON e.tenant_id = ci.tenant_id AND e.id = ci.endpoint_id
		WHERE ci.tenant_id = $1
			AND na.deleted_at IS NULL
			AND ci.deleted_at IS NULL
			AND ($2::uuid IS NULL OR na.id = $2)
			AND ((lower((ci.protocol)::text) = $3))
			AND (TRUE)
		ORDER BY ci.last_verified_at DESC

-- ============================================================
-- tls_version  [shape: crypto_configuration, subject: asset]
-- predicate args: [tls]
SELECT
			na.id AS subject_id,
			ci.tenant_id AS tenant_id,
			ci.last_verified_at AS measured_at,
			ci.protocol_version AS col_0,
			na.hostname AS col_1,
			host(CASE WHEN ci.endpoint_id IS NULL THEN na.primary_address ELSE e.address END) AS col_2,
			e.fqdn AS col_3,
			e.port AS col_4,
			ci.id AS col_5
		FROM crypto_implementations ci
			JOIN assets na ON na.tenant_id = ci.tenant_id AND na.id = ci.asset_id
			LEFT JOIN asset_endpoints e ON e.tenant_id = ci.tenant_id AND e.id = ci.endpoint_id
		WHERE ci.tenant_id = $1
			AND na.deleted_at IS NULL
			AND ci.deleted_at IS NULL
			AND ($2::uuid IS NULL OR na.id = $2)
			AND (((lower((ci.protocol)::text) = $3) AND (ci.protocol_version IS NOT NULL)))
			AND (TRUE)
		ORDER BY ci.last_verified_at DESC
